/* Adapta listas de consulta ao celular sem duplicar registros ou controles. */
(function(root){'use strict';const views=new Set(['dashboard','projects','activities','agenda','supplies','checklist','issues','responsibles','teams','documents','diary']),expandedRows=new Set();
function bind(){let view=location.hash.slice(1)||'dashboard';if(!views.has(view))return;for(let table of document.querySelectorAll('#main .table-wrap > table')){if(table.dataset.mobileReady||table.matches('.sheet,.records-sheet,.gantt,.purchase-sheet,.forecast-sheet'))continue;let headers=[...table.querySelectorAll('thead tr:first-child th')].map(th=>th.textContent.trim());if(!headers.length)continue;table.dataset.mobileReady='1';table.classList.add('mobile-record-table');table.closest('.table-wrap')?.classList.add('mobile-record-wrap');table.closest('.panel')?.classList.add('mobile-card-panel');for(let row of table.querySelectorAll('tbody > tr')){let cells=[...row.children];if(cells.some(td=>td.colSpan>1)){row.classList.add('mobile-summary-row');continue}if(cells.length!==headers.length)continue;let record=row.querySelector('[data-edit][data-id]'),purchase=row.querySelector('[data-action^="purchase-edit:"]'),key=record?record.dataset.edit+':'+record.dataset.id:purchase?purchase.dataset.action:view+':'+cells[0].textContent;let secondary=[];cells.forEach((cell,i)=>{cell.dataset.mobileLabel=headers[i]||'Ações';let content=document.createElement('div');content.className='mobile-cell-value';while(cell.firstChild)content.append(cell.firstChild);cell.append(content);let actions=i===headers.length-1&&(!headers[i]||headers[i]==='Ações'),primary=i===0||i===1||/status|situação|prazo|início|vencimento|total|valor|estoque|saldo|conferência/i.test(headers[i]);if(actions)cell.classList.add('mobile-actions-cell');else if(!primary){cell.classList.add('mobile-secondary-cell');secondary.push(cell)}});if(secondary.length){let cell=document.createElement('td');cell.className='mobile-details-cell';cell.colSpan=headers.length;let button=document.createElement('button');button.type='button';button.className='text-btn mobile-row-details';let initial=expandedRows.has(key);row.classList.toggle('mobile-row-expanded',initial);button.textContent=initial?'Menos detalhes':'Mais detalhes';button.setAttribute('aria-expanded',String(initial));button.addEventListener('click',()=>{let expanded=!row.classList.contains('mobile-row-expanded');row.classList.toggle('mobile-row-expanded',expanded);if(expanded)expandedRows.add(key);else expandedRows.delete(key);button.setAttribute('aria-expanded',String(expanded));button.textContent=expanded?'Menos detalhes':'Mais detalhes'});cell.append(button);row.append(cell)}}}}
root.EngefexMobile={bind};
})(typeof window==='undefined'?globalThis:window);
